33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit logger; each successful owner create emits one line here. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
110	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = normalizeAddress(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        if (owner.getEmail() != null) {
128	            String email = normalizeEmail(owner.getEmail());
129	            if (email == null) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
135	        if (effectiveRegistrationDate == null) {
136	            effectiveRegistrationDate = LocalDate.now();
137	        }
138	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
139	        owner.setRegistrationDate(registrationDate);
140	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
144	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
145	        }
146	        for (Owner existing : this.clinicService.findAllOwners()) {
147	            if (telephone.equals(toE164(existing.getTelephone()))) {
148	                return new ResponseEntity<>(HttpStatus.CONFLICT);
149	            }
150	        }
151	        String lastNameKey = householdKey(owner.getLastName());
152	        String addressKey = householdKey(owner.getAddress());
153	        List<Owner> householdMembers = new ArrayList<>();
154	        for (Owner existing : this.clinicService.findAllOwners()) {
155	            if (lastNameKey.equals(householdKey(existing.getLastName()))
156	                && addressKey.equals(householdKey(existing.getAddress()))) {
157	                householdMembers.add(existing);
158	            }
159	        }
160	        if (!householdMembers.isEmpty()) {
161	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
162	                return new ResponseEntity<>(HttpStatus.CONFLICT);
163	            }
164	            String householdId = householdId(lastNameKey, addressKey);
165	            owner.setHouseholdId(householdId);
166	            for (Owner member : householdMembers) {
167	                if (!householdId.equals(member.getHouseholdId())) {
168	                    member.setHouseholdId(householdId);
169	                    this.clinicService.saveOwner(member);
170	                }
171	            }
172	        }
173	        owner.setTelephone(telephone);
174	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
175	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
176	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
177	        this.clinicService.saveOwner(owner);
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
181	            ownerDto.getMembershipLevel());
182	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        currentOwner.setAddress(ownerFieldsDto.getAddress());
196	        currentOwner.setCity(ownerFieldsDto.getCity());
197	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
198	        currentOwner.setLastName(ownerFieldsDto.getLastName());
199	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
200	        this.clinicService.saveOwner(currentOwner);
201	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Transactional
206	    @Override
207	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        this.clinicService.deleteOwner(owner);
213	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        HttpHeaders headers = new HttpHeaders();
224	        Pet pet = petMapper.toPet(petFieldsDto);
225	        owner.setId(ownerId);
226	        pet.setOwner(owner);
227	        pet.getType().setName(null);
228	        this.clinicService.savePet(pet);
229	        PetDto petDto = petMapper.toPetDto(pet);
230	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
231	            .buildAndExpand(pet.getId()).toUri());
232	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
238	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
239	        if (currentOwner != null) {
240	            Pet currentPet = this.clinicService.findPetById(petId);
241	            if (currentPet != null) {
242	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
243	                currentPet.setName(petFieldsDto.getName());
244	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
245	                this.clinicService.savePet(currentPet);
246	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
247	            }
248	        }
249	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	    }
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
255	        HttpHeaders headers = new HttpHeaders();
256	        Visit visit = visitMapper.toVisit(visitFieldsDto);
257	        Pet pet = new Pet();
258	        pet.setId(petId);
259	        visit.setPet(pet);
260	        this.clinicService.saveVisit(visit);
261	        VisitDto visitDto = visitMapper.toVisitDto(visit);
262	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
263	            .buildAndExpand(visit.getId()).toUri());
264	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
265	    }
266	
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
271	        Owner owner = this.clinicService.findOwnerById(ownerId);
272	        if (owner != null) {
273	            Pet pet = owner.getPet(petId);
274	            if (pet != null) {
275	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
276	            }
277	        }
278	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
279	    }
280	
281	    /**
282	     * The maximum number of owners permitted per city. Owner creation is rejected once the
283	     * owner's city already contains this many owners.
284	     */
285	    private static final int MAX_OWNERS_PER_CITY = 50;
286	
287	    /**
288	     * Counts how many existing owners live in the given city, compared case-insensitively.
289	     * This is evaluated before the new owner is persisted, so the owner being created is not
290	     * included in the count.
291	     *
292	     * @param city the new owner's city
293	     * @return the number of existing owners in that city
294	     */
295	    private int countOwnersInCity(String city) {
296	        int count = 0;
297	        for (Owner existing : this.clinicService.findAllOwners()) {
298	            if (city.equalsIgnoreCase(existing.getCity())) {
299	                count++;
300	            }
301	        }
302	        return count;
303	    }
304	
305	    /**
306	     * The maximum number of owners that may be created in a single business day. Owner
307	     * creation is rejected once this many owners already fall on the new owner's adjusted
308	     * business day {@code registrationDate}.
309	     */
310	    private static final int MAX_OWNERS_PER_DAY = 100;
311	
312	    /**
313	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
314	     * to the following Monday, while a weekday is returned unchanged.
315	     *
316	     * @param date the date to adjust
317	     * @return the same date if it is a weekday, otherwise the following Monday
318	     */
319	    private LocalDate toBusinessDay(LocalDate date) {
320	        DayOfWeek dayOfWeek = date.getDayOfWeek();
321	        if (dayOfWeek == DayOfWeek.SATURDAY) {
322	            return date.plusDays(2);
323	        }
324	        if (dayOfWeek == DayOfWeek.SUNDAY) {
325	            return date.plusDays(1);
326	        }
327	        return date;
328	    }
329	
330	    /**
331	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
332	     * registrationDate} rolls forward to the same business day. This is evaluated before the
333	     * new owner is persisted, so the owner being created is not included in the count.
334	     *
335	     * @param businessDay the adjusted business day to count against
336	     * @return the number of existing owners registered on that business day
337	     */
338	    private int countOwnersRegisteredOn(LocalDate businessDay) {
339	        int count = 0;
340	        for (Owner existing : this.clinicService.findAllOwners()) {
341	            LocalDate existingDate = existing.getRegistrationDate();
342	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
343	                count++;
344	            }
345	        }
346	        return count;
347	    }
348	
349	    /**
350	     * The number of owners that may be created on a single business day before a bulk-signup
351	     * warning is raised. Once more than this many owners already fall on the current business
352	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
353	     */
354	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
355	
356	    /**
357	     * Reports whether an unusually high number of owners have been created for today's business
358	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
359	     * the business day that {@code LocalDate.now()} rolls forward to.
360	     *
361	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
362	     */
363	    private boolean isBulkSignupDay() {
364	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
365	    }
366	
367	    /**
368	     * Builds the customer code for a newly created owner, formatted
369	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
370	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
371	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
372	     * to one more than the number of owners already in that city.
373	     *
374	     * @param city     the owner's city
375	     * @param lastName the owner's last name
376	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
377	     */
378	    private String nextCustomerCode(String city, String lastName) {
379	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
380	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
381	        int sequence = 1;
382	        for (Owner existing : this.clinicService.findAllOwners()) {
383	            if (city.equalsIgnoreCase(existing.getCity())) {
384	                sequence++;
385	            }
386	        }
387	        return String.format("%s-%s-%04d", city3, last3, sequence);
388	    }
389	
390	    /**
391	     * Builds the membership number for a newly created owner, formatted
392	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
393	     * customer code and {@code YY} is the last two digits of the owner's registration
394	     * date year, zero-padded to two digits.
395	     *
396	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
397	     * @param registrationDate the owner's registration date
398	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
399	     */
400	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
401	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
402	    }
403	
404	    /**
405	     * Counts how many existing owners share the given first and last name, compared
406	     * case-insensitively. This is evaluated before the new owner is persisted, so the
407	     * owner being created is not included in the count.
408	     *
409	     * @param firstName the new owner's first name
410	     * @param lastName  the new owner's last name
411	     * @return the number of existing owners with the same first and last name
412	     */
413	    private int countNamesakes(String firstName, String lastName) {
414	        int count = 0;
415	        for (Owner existing : this.clinicService.findAllOwners()) {
416	            if (firstName.equalsIgnoreCase(existing.getFirstName())
417	                && lastName.equalsIgnoreCase(existing.getLastName())) {
418	                count++;
419	            }
420	        }
421	        return count;
422	    }
423	
424	    /**
425	     * Canonical expansions applied to common street-type abbreviations during address
426	     * normalization. Keys and values are upper-cased so the lookup runs after the address
427	     * has itself been upper-cased.
428	     */
429	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
430	        "ST", "STREET",
431	        "RD", "ROAD",
432	        "AVE", "AVENUE");
433	
434	    /**
435	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
436	     * every run of internal whitespace is collapsed to a single space, the result is
437	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
438	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
439	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
440	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
441	     * returned and compared for household duplicates; an address that is blank once
442	     * normalized fails the required-field check.
443	     *
444	     * @param address the raw address value supplied by the client
445	     * @return the normalized address (empty string when {@code address} is null or blank)
446	     */
447	    private static String normalizeAddress(String address) {
448	        if (address == null) {
449	            return "";
450	        }
451	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
452	        if (collapsed.isEmpty()) {
453	            return "";
454	        }
455	        StringBuilder normalized = new StringBuilder(collapsed.length());
456	        for (String token : collapsed.split(" ")) {
457	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
458	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
459	            if (normalized.length() > 0) {
460	                normalized.append(' ');
461	            }
462	            normalized.append(expanded != null ? expanded : token);
463	        }
464	        return normalized.toString();
465	    }
466	
467	    /**
468	     * Normalizes a last name or address for household-duplicate comparison: leading and
469	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
470	     * single space and the result is lower-cased. Two owners are considered to share a
471	     * household when both their last names and addresses produce the same key.
472	     *
473	     * @param value the raw last name or address value
474	     * @return the normalized comparison key (empty string when {@code value} is null)
475	     */
476	    private static String householdKey(String value) {
477	        if (value == null) {
478	            return "";
479	        }
480	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
481	    }
482	
483	    /**
484	     * Derives the stable shared household identifier for the given normalized last name
485	     * and address keys. The identifier is deterministic — the same household (same
486	     * {@link #householdKey normalized} last name and address) always maps to the same
487	     * value — so every owner who joins a household is assigned an identical id. It is the
488	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
489	     * '<lastNameKey>|<addressKey>'}.
490	     *
491	     * @param lastNameKey the normalized last name key
492	     * @param addressKey  the normalized address key
493	     * @return the shared household identifier
494	     */
495	    private static String householdId(String lastNameKey, String addressKey) {
496	        String source = lastNameKey + "|" + addressKey;
497	        try {
498	            byte[] digest = MessageDigest.getInstance("SHA-256")
499	                .digest(source.getBytes(StandardCharsets.UTF_8));
500	            StringBuilder hex = new StringBuilder(digest.length * 2);
501	            for (byte b : digest) {
502	                hex.append(String.format("%02x", b));
503	            }
504	            return hex.substring(0, 12).toUpperCase();
505	        } catch (NoSuchAlgorithmException e) {
506	            throw new IllegalStateException("SHA-256 not available", e);
507	        }
508	    }
509	
510	    /**
511	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
512	     * and brackets are stripped. When the number already carries a leading {@code '+'}
513	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
514	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
515	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
516	     *
517	     * @param telephone the raw telephone value supplied by the client
518	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
519	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
520	     */
521	    private static String toE164(String telephone) {
522	        if (telephone == null) {
523	            return null;
524	        }
525	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
526	        String digits;
527	        if (cleaned.startsWith("+")) {
528	            digits = cleaned.substring(1);
529	        } else {
530	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
531	            digits = "61" + national;
532	        }
533	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
534	    }
535	
536	    /**
537	     * Normalizes an owner email for creation. A present email must be a syntactically
538	     * valid address; the returned value is lower-cased.
539	     *
540	     * @param email the raw email value supplied by the client (never {@code null} here)
541	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
542	     *         address (signalling a 400 Bad Request)
543	     */
544	    private static String normalizeEmail(String email) {
545	        String trimmed = email.trim();
546	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
547	            return null;
548	        }
549	        return trimmed.toLowerCase();
550	    }
551	}
